CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname = 'ledger') THEN
        CREATE SCHEMA ledger;
    END IF;
END $EF$;

CREATE TABLE ledger.entries (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Code" text NOT NULL,
    "Kind" text NOT NULL,
    "Title" text NOT NULL,
    "Note" text,
    "Rank" integer NOT NULL,
    "Score" integer,
    "Period" daterange NOT NULL,
    "Amount_Cents" bigint NOT NULL,
    "Amount_Currency" text NOT NULL,
    CONSTRAINT "PK_entries" PRIMARY KEY ("Id")
);

CREATE INDEX ix_entry_kind_lower ON ledger.entries ((lower("Kind")) COLLATE "C" text_pattern_ops);

CREATE UNIQUE INDEX ux_entry_kind_title ON ledger.entries (("Kind"), (upper("Title")) COLLATE "C" text_pattern_ops DESC NULLS LAST) INCLUDE ("Rank", "Amount_Currency") NULLS NOT DISTINCT WITH (deduplicate_items=false, fillfactor=70) WHERE "Rank" > 0;

CREATE INDEX ix_entry_title_search ON ledger.entries USING gin ((to_tsvector('simple', "Title"))) WITH (fastupdate=false, gin_pending_list_limit=128);

CREATE INDEX ix_entry_period ON ledger.entries USING gist (("Period")) WITH (buffering='auto', fillfactor=90);

CREATE INDEX ix_entry_rank_brin ON ledger.entries USING brin (("Rank" + 0)) WITH (autosummarize=true, pages_per_range=16);

CREATE INDEX ix_entry_code_hash ON ledger.entries USING hash ((lower("Code")));

CREATE INDEX ix_entry_title_sp ON ledger.entries USING spgist ((lower("Title")));

COMMIT;

CREATE INDEX CONCURRENTLY ix_entry_code_upper ON ledger.entries ((upper("Code")));

START TRANSACTION;
CREATE INDEX "IX_entries_Kind_Score_Amount_Currency" ON ledger.entries ("Kind", "Score" NULLS FIRST, "Amount_Currency") INCLUDE ("Title") WITH (fillfactor=80);

CREATE INDEX "IX_entries_lowerTitle" ON ledger.entries ((lower("Title"))) WHERE "Note" IS NOT NULL;

COMMIT;

INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
VALUES ('20260101000000_Initial', '10.0.15');

START TRANSACTION;
DROP INDEX ledger.ix_entry_kind_lower;

DROP INDEX ledger.ux_entry_kind_title;

DROP INDEX ledger.ix_entry_code_upper;

CREATE UNIQUE INDEX ux_entry_kind_title ON ledger.entries (("Kind"), (upper("Title")) COLLATE "C" text_pattern_ops DESC NULLS LAST) INCLUDE ("Rank", "Amount_Currency") NULLS NOT DISTINCT WITH (deduplicate_items=false, fillfactor=70) WHERE "Rank" > 1;

CREATE INDEX ix_entry_note_lower ON ledger.entries ((lower("Note")));

INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
VALUES ('20260102000000_Changed', '10.0.15');

COMMIT;

